<script setup lang="ts">
import {onMounted,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {showConfirmDialog,showToast} from 'vant';import {confirmPositioning,getPositioningCard,rejectPositioning,type PositioningCard} from '@/api/positioning';
const route=useRoute(),router=useRouter(),card=ref<PositioningCard>(),pending=ref(false),loading=ref(true),error=ref(false),errorMessage=ref(''),submitting=ref(false);
const load=async()=>{loading.value=true;error.value=false;errorMessage.value='';try{const response=await getPositioningCard(Number(route.params.id));const r=(response as any)?.data?.data??(response as any)?.data??response;if(!r||typeof r.state!=='string')throw new Error('定位接口未返回有效状态');pending.value=r.state!=='ready';card.value=r.card}catch(ex){error.value=true;errorMessage.value=ex instanceof Error?ex.message:'定位方案加载失败'}finally{loading.value=false}};
const confirm=async()=>{if(!card.value)return;submitting.value=true;try{await confirmPositioning(card.value.id,card.value.version);showToast('确认成功');router.replace('/home')}finally{submitting.value=false}};
const reject=async()=>{if(!card.value)return;const ok=await showConfirmDialog({title:'退回编导',message:'将退回原编导重新修改'}).catch(()=>null);if(!ok)return;submitting.value=true;try{await rejectPositioning(card.value.id,card.value.version,'学员不认可定位方案');showToast('已退回编导');router.replace('/home')}finally{submitting.value=false}};onMounted(load)
</script>
<template><main><van-nav-bar title="定位方案确认" left-arrow @click-left="router.back()"/><van-loading v-if="loading" vertical>加载中</van-loading><van-empty v-else-if="error" :description="errorMessage||'加载失败'"><van-button size="small" @click="load">重试</van-button></van-empty><van-empty v-else-if="pending" description="兼职账号尚未绑定学员，请联系工作人员补充后再确认"/><template v-else-if="card"><van-cell-group inset><van-cell title="定位编号" :value="card.cardNo"/><van-cell title="状态" :value="card.status"/><van-cell title="第一层定位" :label="card.layer1Json||'未填写'"/><van-cell title="第二层定位" :label="card.layer2Json||'未填写'"/><van-cell title="定位公式" :label="card.formulaJson||'未填写'"/></van-cell-group><div style="padding:20px;display:grid;gap:12px"><van-button type="primary" block :loading="submitting" @click="confirm">认可并进入试跑</van-button><van-button block :loading="submitting" @click="reject">不认可，退回编导</van-button></div></template></main></template>
